widget.solution:
def profit(legs, S):
    """Total profit at expiry of (kind, qty, strike, premium) legs."""
    total = 0.0
    for kind, qty, strike, premium in legs:
        if kind == "call":
            total += qty * (max(S - strike, 0) - premium)
        elif kind == "put":
            total += qty * (max(strike - S, 0) - premium)
        elif kind == "stock":
            total += qty * (S - strike)
    return total
